//! `upper`/`lower` over every Unicode scalar value against the mapping each
//! Spark release produced (`tests/fixtures/spark-<ver>/case-mapping.json`,
//! generated by `tests/scripts/gen_case_mapping.py`): 4.0 and 4.1 do not map
//! the code points that gained a mapping in Unicode 17.
#![forbid(unsafe_code)]

use std::collections::BTreeMap;

use arrow_array::StringArray;
use krishiv_kernels::string::{lower, upper};
use krishiv_kernels::{KernelCtx, SparkVersion};
use serde_json::Value;

type R = Result<(), Box<dyn std::error::Error>>;

/// code point -> mapped code points, for the scalars Spark changes.
fn table(v: &Value, key: &str) -> BTreeMap<u32, Vec<u32>> {
    let mut out = BTreeMap::new();
    if let Some(m) = v.get(key).and_then(Value::as_object) {
        for (cp, mapped) in m {
            let cps = mapped
                .as_array()
                .map(|a| {
                    a.iter()
                        .filter_map(Value::as_u64)
                        .filter_map(|c| u32::try_from(c).ok())
                        .collect()
                })
                .unwrap_or_default();
            if let Ok(cp) = cp.parse() {
                out.insert(cp, cps);
            }
        }
    }
    out
}

#[test]
fn every_scalar_maps_as_in_spark() -> R {
    let scalars: Vec<char> = (0..=0x10_FFFF_u32).filter_map(char::from_u32).collect();
    let strings: Vec<String> = scalars.iter().map(char::to_string).collect();
    let input = StringArray::from_iter_values(&strings);
    for (dir, version) in [
        ("spark-4.0.0", SparkVersion::V4_0),
        ("spark-4.1.0", SparkVersion::V4_1),
        ("spark-4.2.0", SparkVersion::V4_2),
    ] {
        let path = krishiv_testkit::tests_dir().join(format!("fixtures/{dir}/case-mapping.json"));
        let fixture: Value = serde_json::from_str(&std::fs::read_to_string(path)?)?;
        let (up, low) = (table(&fixture, "upper"), table(&fixture, "lower"));
        assert_eq!(
            u64::try_from(scalars.len())?,
            fixture["scalars"].as_u64().unwrap_or(0)
        );
        let ctx = KernelCtx::new().with_spark_version(version);
        let (u, l) = (upper(&input, &ctx)?, lower(&input, &ctx)?);
        let mut bad = Vec::new();
        for (i, c) in scalars.iter().enumerate() {
            let cp = u32::from(*c);
            for (name, got, want) in [("upper", &u, &up), ("lower", &l, &low)] {
                let expected: String = want.get(&cp).map_or_else(
                    || c.to_string(),
                    |m| m.iter().filter_map(|x| char::from_u32(*x)).collect(),
                );
                if got.value(i) != expected {
                    bad.push(format!(
                        "{name}(U+{cp:04X}) = {:?}, Spark {expected:?}",
                        got.value(i)
                    ));
                }
            }
        }
        assert!(
            bad.is_empty(),
            "{dir}: {} differences, first: {:?}",
            bad.len(),
            &bad[..bad.len().min(20)]
        );
    }
    Ok(())
}
